package cn.nulladev.modularmagic;

import cn.nulladev.modularmagic.research.*;
import cn.nulladev.modularmagic.registry.ModContent;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.inventory.ClickType;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.gametest.*;
import java.util.UUID;

@GameTestHolder(ModularMagic.MOD_ID)
@PrefixGameTestTemplate(false)
public final class RuneTableGameTests {
    @GameTest(template="empty",batch="rune_tables") public static void researchUsesPackInkAndDiscardsUnfinishedProgress(GameTestHelper h){
        var p=player(h);ResearchCatalog.get("K00").nodes().forEach(n->ResearchKnowledge.learn(p,n));p.getInventory().setItem(1,ResearchContent.INK.toStack());var m=table(h,p,false);m.supplies.setItem(0,ResearchNoteItem.create("K01",false));m.layout(620,344);
        h.assertTrue(m.slots.subList(10,46).stream().allMatch(s->s.isActive()&&s.mayPlace(new ItemStack(Items.DIAMOND))&&s.mayPickup(p))&&m.slots.get(0).isActive()&&!m.slots.get(0).mayPickup(p)&&m.slots.get(1).isActive()&&m.slots.get(1).mayPlace(ResearchContent.INK.toStack())&&!m.slots.get(1).mayPlace(new ItemStack(Items.DIAMOND)),"Backpack is accessible; physical node gems still cannot enter the paper or ink slots");
        int cost=m.inkCost;m.apply(m.revision,"{\"op\":\"start\"}");h.assertTrue(m.paid&&p.getInventory().getItem(1).getDamageValue()==cost,"Ink is taken from the pack once");
        m.apply(m.revision,"{\"op\":\"start\"}");h.assertTrue(p.getInventory().getItem(1).getDamageValue()==cost,"Start cannot double charge");m.removed(p);
        h.assertTrue(m.supplies.getItem(0).isEmpty()&&p.getInventory().items.stream().anyMatch(s->s.is(ResearchContent.NOTE.get())),"An unfinished physical note must be returned");
        h.assertTrue(ResearchKnowledge.state(p).getString("paid:effect/push").isEmpty()&&ResearchKnowledge.state(p).getString("draft:effect/push").isEmpty(),"Closing discards the paid attempt and draft");
        var again=new ResearchMenu(9,p.getInventory(),m.pos,false);again.supplies.setItem(0,ResearchNoteItem.create("K01",false));h.assertTrue(!again.paid&&again.document.nodes().size()==1,"The next attempt starts from a blank tree");again.removed(p);h.succeed();
    }
    @GameTest(template="empty",batch="rune_tables") public static void insufficientInkCannotPartiallyPayAndInventoryInkCanBeMoved(GameTestHelper h){
        var p=player(h);ResearchCatalog.get("K00").nodes().forEach(n->ResearchKnowledge.learn(p,n));var ink=ResearchContent.INK.toStack();ink.setDamageValue(31);p.getInventory().setItem(1,ink);var m=table(h,p,false);m.supplies.setItem(0,ResearchNoteItem.create("K01",false));m.apply(m.revision,"{\"op\":\"start\"}");h.assertTrue(!m.paid&&m.notice.equals("ink")&&ink.getDamageValue()==31,"A shortage leaves ink and editing locked");h.assertTrue(!m.quickMoveStack(p,38).isEmpty()&&p.getInventory().getItem(1).isEmpty()&&m.supplies.getItem(1).getDamageValue()==31,"Pack ink can be shifted into the dedicated supply slot");m.removed(p);h.succeed();
    }
    @GameTest(template="empty",batch="rune_tables") public static void closingWithFullPackDropsTheNote(GameTestHelper h){
        var p=player(h);var m=table(h,p,false);m.supplies.setItem(0,ResearchNoteItem.create("K01",false));for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));m.removed(p);
        h.assertTrue(m.supplies.getItem(0).isEmpty()&&h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,p.getBoundingBox().inflate(4)).stream().anyMatch(e->e.getItem().is(ResearchContent.NOTE.get())),"A full pack returns the unfinished note to the ground without blocking close");h.succeed();
    }
    private static ServerPlayer player(GameTestHelper h){var p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"TableTester"));p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.setPos(h.absolutePos(new BlockPos(1,2,1)).getCenter());return p;}
    private static ResearchMenu table(GameTestHelper h,ServerPlayer p,boolean carving){var pos=h.absolutePos(new BlockPos(1,1,1));h.getLevel().setBlockAndUpdate(pos,(carving?ResearchContent.CARVER:ResearchContent.TABLE).get().defaultBlockState());return new ResearchMenu(8,p.getInventory(),pos,carving);}
    @GameTest(template="empty",batch="rune_tables") public static void carvingUsesTableSlotsAndKeepsTheOutputUntilTaken(GameTestHelper h){var p=player(h);ResearchKnowledge.learn(p,"effect/push");var m=table(h,p,true);p.getInventory().setItem(0,new ItemStack(ResearchContent.BLANK.get(),4));p.getInventory().setItem(1,ResearchContent.INK.toStack());m.apply(m.revision,"{\"op\":\"carve\",\"id\":\"effect/push\"}");h.assertTrue(m.supplies.getItem(9).isEmpty()&&p.getInventory().getItem(0).getCount()==4,"Carving must not silently consume pack materials");m.quickMoveStack(p,37);m.quickMoveStack(p,38);h.assertTrue(m.supplies.getItem(0).getCount()==4&&m.supplies.getItem(1).isEmpty(),"Carving accepts blank gems and leaves ink in the backpack");m.apply(m.revision,"{\"op\":\"carve\",\"id\":\"effect/push\"}");h.assertTrue(m.supplies.getItem(9).is(ModContent.NODES.get("effect/push").get())&&m.supplies.getItem(0).getCount()==3&&p.getInventory().getItem(1).getDamageValue()==0,"Carving only uses one blank gem and no auxiliary material");m.removed(p);var saved=((RuneTableBlockEntity)h.getLevel().getBlockEntity(m.pos)).saveWithoutMetadata(h.getLevel().registryAccess());var be=(RuneTableBlockEntity)h.getLevel().getBlockEntity(m.pos);be.inventory.clearContent();be.loadWithComponents(saved,h.getLevel().registryAccess());var reopen=new ResearchMenu(9,p.getInventory(),m.pos,true);h.assertTrue(reopen.supplies.getItem(0).getCount()==3&&reopen.supplies.getItem(9).is(ModContent.NODES.get("effect/push").get()),"Supplies and output survive closing and saving");reopen.quickMoveStack(p,9);h.assertTrue(reopen.supplies.getItem(9).isEmpty()&&p.getInventory().items.stream().anyMatch(s->s.is(ModContent.NODES.get("effect/push").get())),"The output can be shift-clicked into the backpack");reopen.removed(p);h.succeed();}
    @GameTest(template="empty",batch="rune_tables") public static void aFullOutputCannotEatMoreMaterials(GameTestHelper h){var p=player(h);ResearchKnowledge.learn(p,"effect/push");var m=table(h,p,true);m.supplies.setItem(0,ResearchContent.BLANK.toStack());m.supplies.setItem(1,ResearchContent.INK.toStack());m.supplies.setItem(9,new ItemStack(Items.STONE,64));m.apply(m.revision,"{\"op\":\"carve\",\"id\":\"effect/push\"}");h.assertTrue(m.supplies.getItem(0).getCount()==1&&m.supplies.getItem(1).getDamageValue()==0,"Blocked output must preserve every input");h.assertTrue(!m.slots.get(9).mayPlace(new ItemStack(Items.STONE)),"Output slot rejects player insertion");m.removed(p);h.succeed();}
    @GameTest(template="empty",batch="rune_tables") public static void researchRequiresNotesAndLeavesVirtualNodesOutOfInventory(GameTestHelper h){var p=player(h);ResearchCatalog.get("K00").nodes().forEach(n->ResearchKnowledge.learn(p,n));var m=table(h,p,false);h.assertTrue(m.document==null,"An empty desk must not invent a research note");m.supplies.setItem(0,ResearchNoteItem.create("K01",false));m.supplies.setItem(1,ResearchContent.INK.toStack());int price=m.inkCost;m.apply(m.revision,"{\"op\":\"start\"}");h.assertTrue(m.paid&&m.supplies.getItem(1).getDamageValue()==price&&!m.supplies.getItem(0).isEmpty(),"Research spends table ink once and keeps the unfinished note");int items=p.getInventory().items.stream().mapToInt(ItemStack::getCount).sum();m.apply(m.revision,"{\"op\":\"insert\",\"parent\":\""+m.document.root.id+"\",\"slot\":\"trigger_type\",\"index\":0,\"template\":\"trigger/self_pos\"}");h.assertTrue(m.document.nodes().size()==2&&p.getInventory().items.stream().mapToInt(ItemStack::getCount).sum()==items&&m.getCarried().isEmpty(),"Virtual insertion never consumes or creates physical pieces");m.removed(p);var again=new ResearchMenu(9,p.getInventory(),m.pos,false);h.assertTrue(!again.paid&&again.document==null&&again.supplies.getItem(1).getDamageValue()==price,"Unfinished research returns its note and discards its draft and payment");again.removed(p);h.succeed();}
}
